import json
import novamind_api as nm

USAGE_EST = {
    'E1': 48.0,
    'E2': 240.0,
    'E3': 138.0,
    'D_E01': 123.0,
    'D_E02': 66.0,
    'D_E03': 185.0,
    'D_E04': 154.0,
    'D_E05': 139.0,
    'D_E06': 77.0,
    'D_E07': 200.0,
    'D_E08': 139.0,
    'D_E09': 72.0,
    'D_E10': 99.0,
}

# Capacity-yield-optimized offers [C, B, A] per group
INIT_OFFERS = {
    'E1':    {'C': 48.0,  'B': 42.0,  'A': 34.0},   # Low $/u/d: only take if >= $1.0/u/d!
    'E2':    {'C': 220.0, 'B': 195.0, 'A': 150.0},  # Huge usage (240 u/d): only take if >= $0.90/u/d!
    'E3':    {'C': 150.0, 'B': 135.0, 'A': 95.0},
    'D_E01': {'C': 180.0, 'B': 160.0, 'A': 115.0},
    'D_E02': {'C': 102.0, 'B': 88.0,  'A': 62.0},
    'D_E03': {'C': 240.0, 'B': 215.0, 'A': 155.0},
    'D_E04': {'C': 210.0, 'B': 185.0, 'A': 135.0},
    'D_E05': {'C': 160.0, 'B': 140.0, 'A': 100.0},
    'D_E06': {'C': 108.0, 'B': 94.0,  'A': 68.0},
    'D_E07': {'C': 225.0, 'B': 200.0, 'A': 145.0},
    'D_E08': {'C': 190.0, 'B': 168.0, 'A': 120.0},
    'D_E09': {'C': 118.0, 'B': 102.0, 'A': 74.0},
    'D_E10': {'C': 95.0,  'B': 82.0,  'A': 60.0},   # Low $/u/d: only take if >= $0.95/u/d!
}

LOW_YIELD_GROUPS = {'E1', 'E2', 'D_E10'}
HIGH_YIELD_GROUPS = {'D_E01', 'D_E02', 'D_E03', 'D_E04', 'D_E05', 'D_E06', 'D_E07', 'D_E08', 'D_E09', 'E3'}
TIER_COST_PER_U_MO = {1: 0.009, 2: 0.06, 3: 0.18, 4: 0.36, 5: 0.90}

def get_current_plan_tiers():
    row = nm.query("SELECT tier_A, tier_B, tier_C FROM config_history ORDER BY day DESC LIMIT 1")['rows'][0]
    return {'A': row['tier_A'], 'B': row['tier_B'], 'C': row['tier_C']}

def min_profitable_price(group, plan, plan_tiers, capacity_premium=True):
    u = USAGE_EST.get(group, 120.0)
    cost = u * TIER_COST_PER_U_MO[plan_tiers[plan]]
    if capacity_premium:
        # Strict shadow price on low-yield groups to preserve Tier 7 300M/d capacity for $1+/u/d whales!
        if group in LOW_YIELD_GROUPS:
            return round(max(cost + 20.0, u * 0.85), 1)
        return round(max(cost + 18.0, u * 0.65), 1)
    return round(cost + 12.0, 1)

def reply_all_enterprise(plan_tiers=None, capacity_premium=True, reject_low_yield_new=False):
    if plan_tiers is None:
        plan_tiers = get_current_plan_tiers()

    pending = nm.query("""
        WITH last_turns AS (
            SELECT t.*, ROW_NUMBER() OVER (PARTITION BY t.thread_id ORDER BY t.turn_number DESC) AS rn
            FROM enterprise_turns t
            WHERE t.thread_id IN (SELECT thread_id FROM enterprise_turns GROUP BY thread_id HAVING MAX(closed) = 0)
        )
        SELECT lt.customer_id, c.group_id, lt.thread_type, lt.sender AS last_sender,
               lt.turn_number, lt.seat_count, lt.offer_json, lt.message_text,
               s.plan AS cur_plan, s.effective_price AS cur_price
        FROM last_turns lt
        JOIN customers c ON lt.customer_id = c.customer_id
        LEFT JOIN subscriptions s ON lt.customer_id = s.customer_id AND s.status = 'subscribed'
        WHERE lt.rn = 1 AND lt.sender IN ('system', 'customer')
        ORDER BY lt.day, lt.customer_id
    """)['rows']

    deals = []
    rejects = []
    stats = {}
    for row in pending:
        cid = row['customer_id']
        g = row['group_id']
        ttype = row['thread_type']
        turn = row['turn_number']

        if reject_low_yield_new and g in LOW_YIELD_GROUPS and ttype == 'new_lead':
            rejects.append({'customer_id': cid})
            key = f"{g}:rejected_low_yield"
            stats[key] = stats.get(key, 0) + 1
            continue

        base = INIT_OFFERS.get(g, {'C': 110.0, 'B': 95.0, 'A': 70.0})
        floors = {p: min_profitable_price(g, p, plan_tiers, capacity_premium=capacity_premium) for p in ('C', 'B', 'A')}

        c_price = None
        try:
            oj = json.loads(row['offer_json'] or '{}')
            if isinstance(oj, dict) and 'price' in oj and oj['price'] is not None:
                c_price = float(oj['price'])
        except Exception:
            pass

        if ttype in ('churn_prevention', 'renewal'):
            cur_p = row['cur_price'] or base['C']
            if g in LOW_YIELD_GROUPS:
                # Hold firm on low-yield groups — if they churn, they free Tier 7 capacity for $1+/u/d whales!
                offers = [[p, max(round(cur_p, 1), round(USAGE_EST[g] * 0.55, 1))] for p in ('C', 'B', 'A')]
            else:
                # Retain high-yield whales smoothly!
                offers = []
                for p in ('C', 'B', 'A'):
                    target = round(cur_p * 0.90, 1) if p == row['cur_plan'] else round(base[p] * 0.85, 1)
                    if c_price is not None and c_price >= floors[p]:
                        target = min(target, round(max(floors[p], c_price * 1.04), 1))
                    offers.append([p, max(floors[p], target)])
        elif row['last_sender'] == 'system' or turn == 0:
            offers = [[p, max(floors[p], base[p])] for p in ('C', 'B', 'A')]
        else:
            step = max(0.72, 0.91 ** ((turn + 1) // 2))
            offers = []
            for p in ('C', 'B', 'A'):
                target = round(base[p] * step, 1)
                if c_price is not None and c_price >= floors[p]:
                    target = min(target, round(max(floors[p], c_price * 1.06), 1))
                offers.append([p, max(floors[p], target)])

        deals.append([cid, offers])
        key = f"{g}:{ttype}"
        stats[key] = stats.get(key, 0) + 1

    ok = 0
    fail = 0
    for i in range(0, len(deals), 200):
        batch = deals[i:i+200]
        res = nm.enterprise.send_enterprise_deal(deals=batch)
        for r in res.get('results', []):
            if r.get('success'):
                ok += 1
            else:
                fail += 1
                if fail <= 10:
                    print("  FAILED:", r)

    rej_ok = 0
    for i in range(0, len(rejects), 200):
        batch = rejects[i:i+200]
        res = nm.enterprise.reject_enterprise_deal(deals=batch)
        for r in res.get('results', []):
            if r.get('success'):
                rej_ok += 1

    print(f"Enterprise replies: {ok} ok, {fail} failed, {rej_ok} rejected. Breakdown: {stats}")
    return ok, fail

